// If it's validation, stop here (already handled)
if ($input.first().json.query?.validationToken) {
  return [];
}

// Check the changeType - only process "created" events
const notification = $input.first().json.body?.value?.[0];
const changeType = notification?.changeType;

if (changeType !== 'created') {
  return [];
}

// Extract user ID and event ID from resource path
// Format: "Users/{GUID}/Events/{eventId}" (capital U and E)
const resource = notification?.resource || '';
const match = resource.match(/^[Uu]sers\/([^\/]+)\/[Ee]vents\/(.+)$/);

const userId = match ? match[1] : '';
const eventId = match ? match[2] : (notification?.resourceData?.id || '');

if (!userId || !eventId) {
  return [];
}

return [{
  json: {
    ...$input.first().json,
    userEmail: userId,
    eventResourceId: eventId
  }
}];

const event = $('Get Event via Graph').first().json;
const userEmail = $('Validate & Extract User').first().json.userEmail;
const accessToken = $('Get access token').first().json.access_token;
const rawJoinUrl = event.onlineMeeting?.joinUrl;

const joinUrl = rawJoinUrl ? decodeURIComponent(rawJoinUrl) : '';
const isTeamEvent = userEmail.toLowerCase() === 'team@company.com';

const bodyContent = event.body?.content || '';
const isHubSpotMeeting = 
  bodyContent.includes('app.hubspot.com/meetings') &&
  (bodyContent.includes('rescheduleId=') || bodyContent.includes('cancelId='));

const attendees = event.attendees || [];
const hasYour Name = attendees.some(a => a.emailAddress?.address === 'person1@company.com');
const hasAli = attendees.some(a => a.emailAddress?.address === 'person2@company.com');
const hasAde = attendees.some(a => a.emailAddress?.address === 'adeyinka.adeleke@yourcompany.com');
const allAttendeesPresent = hasYour Name && hasAli && hasAde;

const encodedEventId = encodeURIComponent(event.id || '');

return [{
  json: {
    userEmail: userEmail,
    accessToken: accessToken,
    joinUrl: joinUrl,
    hasJoinUrl: !!rawJoinUrl,
    isTeamEvent: isTeamEvent,
    isHubSpotMeeting: isHubSpotMeeting,
    allAttendeesPresent: allAttendeesPresent,
    shouldAddAttendees: isTeamEvent && isHubSpotMeeting && !allAttendeesPresent,
    encodedEventId: encodedEventId,
    existingAttendees: attendees
  }
}];

const data = $('Process Event Data').first().json;
const existingAttendees = data.existingAttendees || [];

const toAdd = [
  "person1@company.com",
  "person2@company.com",
  "adeyinka.adeleke@yourcompany.com"
];

const existingEmails = new Set(
  existingAttendees.map(a => (a.emailAddress?.address || '').toLowerCase())
);

const newAttendees = toAdd
  .filter(email => !existingEmails.has(email.toLowerCase()))
  .map(email => ({ emailAddress: { address: email }, type: "optional" }));

const allAttendees = [...existingAttendees, ...newAttendees];

return [{
  json: {
    accessToken: data.accessToken,
    userEmail: data.userEmail,
    encodedEventId: data.encodedEventId,
    attendees: allAttendees
  }
}];

const body = $input.first().json;
const allSubs = body.value || [];
const accessToken = $('Get Token (Renewal)').first().json.access_token;

const matching = allSubs.filter(sub =>
  sub.notificationUrl && sub.notificationUrl.includes('microsoft-calendar')
);

if (matching.length === 0) {
  return [{ json: { subscriptionId: null, nothingToDelete: true, accessToken: accessToken } }];
}

return matching.map(sub => ({
  json: {
    subscriptionId: sub.id,
    nothingToDelete: false,
    accessToken: accessToken
  }
}));

// Get all users from paginated results, filter to @yourcompany.com internal users
const items = $input.all();
const allUsers = [];

for (const item of items) {
  const users = item.json.value || [item.json];
  for (const u of users) {
    const upn = (u.userPrincipalName || '').toLowerCase();
    const mail = (u.mail || '').toLowerCase();
    if (upn.endsWith('@yourcompany.com') && !upn.includes('#ext#')) {
      allUsers.push({ email: mail || upn, displayName: u.displayName || '' });
    }
  }
}

// Ensure team@company.com is included
const hasTeam = allUsers.some(u => u.email === 'team@company.com');
if (!hasTeam) {
  allUsers.push({ email: 'team@company.com', displayName: 'YourCompany Team' });
}

// Deduplicate by email
const seen = new Set();
const unique = [];
for (const u of allUsers) {
  if (!seen.has(u.email)) {
    seen.add(u.email);
    unique.push(u);
  }
}

return unique.map(u => ({ json: { email: u.email, displayName: u.displayName } }));

const email = $input.first().json.email;

const expirationDate = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000);
const expirationDateTime = expirationDate.toISOString();

return [{
  json: {
    changeType: "created",
    notificationUrl: "https://[your-n8n-domain]/webhook/microsoft-calendar",
    resource: "users/" + email + "/events",
    expirationDateTime: expirationDateTime,
    clientState: "[your-webhook-secret]"
  }
}];

